package org.xingmu.tv;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.Locale;
/** Inspect extensionless endpoints before choosing a Media3 media source. */
final class MediaFormat {
 static String infer(String contentType,String prefix){String type=contentType==null?"":contentType.toLowerCase(Locale.ROOT);String start=prefix.replace("\ufeff","").trim();if(start.startsWith("#EXTM3U")||type.contains("mpegurl"))return "application/x-mpegURL";if(type.contains("dash+xml")||start.matches("(?s).*<MPD(?:\\s|>).*"))return "application/dash+xml";if(type.contains("video/mp2t"))return "video/mp2t";return null;}
 static String probe(String address,String ua)throws IOException{String lower=address.toLowerCase(Locale.ROOT).split("[?#]",2)[0];if(lower.endsWith(".m3u8"))return "application/x-mpegURL";if(lower.endsWith(".mpd"))return "application/dash+xml";if(lower.endsWith(".mp4")||lower.endsWith(".mkv")||lower.endsWith(".ts"))return null;for(int hop=0;hop<5;hop++){if(!CatalogParser.safeMediaUrl(address))throw new IOException("播放地址不支持");HttpURLConnection c=(HttpURLConnection)new URL(address).openConnection();c.setConnectTimeout(4000);c.setReadTimeout(4000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent",ua);try{int status=c.getResponseCode();if(status>=300&&status<400){String location=c.getHeaderField("Location");if(location==null)throw new IOException("播放跳转缺少地址");address=new URL(new URL(address),location).toString();continue;}if(status!=200&&status!=206)throw new IOException("HTTP "+status);byte[] bytes=new byte[512];int size=0;try(InputStream in=c.getInputStream()){while(size<bytes.length){int n=in.read(bytes,size,bytes.length-size);if(n<0)break;size+=n;}}return infer(c.getContentType(),new String(bytes,0,size,StandardCharsets.UTF_8));}finally{c.disconnect();}}throw new IOException("播放跳转次数过多");}
}
